package ferry.testkit.tla

import java.nio.charset.StandardCharsets
import java.nio.file.{Files, Path}

import scala.jdk.CollectionConverters.*

/**
 * Random behaviours of a spec, generated by TLC in simulation mode (`-simulate file=…,num=N -depth D`), for replaying
 * through the code (model → code).
 *
 * TLC writes each behaviour as a module of states, each a conjunction `/\ variable = value`, preceded by a comment that
 * names the action that led to it. [[Behaviours.parse]] reads one such file back into states.
 */
object Behaviours:

  /** One state of a behaviour: the action that reached it (as TLC labels it) and every variable's value. */
  final case class State(action: String, variables: Map[String, Value]):
    def apply(variable: String): Value = variables(variable)

  type Behaviour = Vector[State]

  /**
   * Generates `count` behaviours of up to `depth` steps of `spec` under `config` (both in `formal`), with `seed`. The
   * configuration's temporal properties are dropped: simulation is only asked for behaviours here.
   */
  def generate(
    formal: Path,
    spec: String,
    config: String,
    count: Int,
    depth: Int,
    seed: Long,
    alter: Alter = Alter.none
  ): Either[Tlc.Verdict, Vector[Behaviour]] =
    if Tlc.jar.isEmpty then Left(Tlc.Verdict.Skipped("TLC not found: set TLA2TOOLS or put tla2tools.jar at the root"))
    else
      val scratch = Files.createTempDirectory("behaviours")
      try
        Alter.copy(formal, scratch, alter)
        val cfg = Files
          .readAllLines(formal.resolve(s"$config.cfg"))
          .asScala
          .filterNot(l => l.trim.startsWith("PROPERTIES") || l.trim.startsWith("PROPERTY"))
          .mkString("\n")
        Files.writeString(scratch.resolve("Replay.cfg"), cfg, StandardCharsets.UTF_8)
        val out = scratch.resolve("out")
        Files.createDirectories(out)
        val args = Seq("-simulate", s"file=${out.resolve("behaviour")},num=$count", "-depth", depth.toString) ++
          Seq("-seed", seed.toString, "-deadlock")
        Tlc.run(scratch, s"$spec.tla", "Replay.cfg", args) match
          case None                                 => Left(Tlc.Verdict.Skipped("TLC not found"))
          case Some(o) if o.text.contains("Error:") => Left(Tlc.Verdict.ToolError(Tlc.summary(o.text)))
          case Some(_)                              =>
            val files = Files.list(out).iterator().asScala.toVector.sortBy(_.getFileName.toString)
            files.traverse(f => parse(Files.readString(f))).left.map(Tlc.Verdict.ToolError(_))
      finally Tlc.deleteRecursively(scratch)

  private val Label = """\\\* <([^ >]+)""".r

  /** Parses one behaviour, as TLC writes it. */
  def parse(text: String): Either[String, Behaviour] =
    val blocks = text.split("\n(?=STATE_\\d+ ==)").toVector.drop(1)
    val lines  = text.linesIterator.toVector
    val labels = lines.collect { case l if l.startsWith("\\* <") => Label.findFirstMatchIn(l).fold("?")(_.group(1)) }
    blocks.zipWithIndex.traverse { (block, i) =>
      // Each conjunct starts a line with `/\ `; a long value continues on the lines after it. Comments (the label of
      // the next state) and the end of the module are not part of the state.
      val body = block.linesIterator.drop(1).filterNot(l => l.startsWith("\\*") || l.startsWith("====")).mkString("\n")
      val conjuncts = body.split("\n(?=/\\\\ )").toVector.map(_.trim).filter(_.startsWith("/\\"))
      conjuncts
        .traverse { c =>
          val conjunct = c.stripPrefix("/\\").trim
          val eq       = conjunct.indexOf('=')
          if eq < 0 then Left(s"not a conjunct: $c")
          else Value.parse(conjunct.drop(eq + 1)).map(conjunct.take(eq).trim -> _)
        }
        .map(vars => State(labels.lift(i).getOrElse("?"), vars.toMap))
    }

  extension [A](xs: Vector[A])
    private def traverse[B](f: A => Either[String, B]): Either[String, Vector[B]] =
      xs.foldLeft(Right(Vector.empty): Either[String, Vector[B]])((acc, x) => acc.flatMap(bs => f(x).map(bs :+ _)))
